def _blit(fb: "Canvas", data: bytes, size: int, x: int, y: int, c: int) -> None:  # noqa: PLR0913, PLR0917 -- a bitmap, its edge, where and in what colour
    stride = (size + 7) // 8
    for row in range(size):
        base = row * stride
        for col in range(size):
            if data[base + (col >> 3)] & (0x80 >> (col & 7)):
                fb.pixel(x + col, y + row, c)


def draw_icon(fb: "Canvas", name: str, x: int, y: int, c: int = 1) -> None:
    """Draw a pixel icon with its top-left corner at (x, y).

    Args:
        fb: The framebuffer to draw on.
        name: The icon's name, as in ICONS.
        x: The left column.
        y: The top row.
        c: The colour of the lit pixels; the others are left as they are.

    Raises:
        ValueError: When there is no pixel icon of that name.
    """
    data = ICONS.get(name)
    if data is None:
        raise ValueError("no pixel icon named " + name)
    _blit(fb, data, ICON_SIZE, x, y, c)


def draw_mark(fb: "Canvas", size: int, x: int, y: int, c: int = 1) -> None:
    """Draw the Qualithm mark with its top-left corner at (x, y).

    Args:
        fb: The framebuffer to draw on.
        size: The mark's edge in pixels, a key of MARKS.
        x: The left column.
        y: The top row.
        c: The colour of the lit pixels; the others are left as they are.

    Raises:
        ValueError: When the mark isn't cut at that size.
    """
    data = MARKS.get(size)
    if data is None:
        raise ValueError("no pixel mark at size " + str(size))
    _blit(fb, data, size, x, y, c)


def glyph(ch: str) -> bytes:
    """The 5 column bytes of a character, top row bit 0.

    Args:
        ch: One character; one outside printable ASCII gets FALLBACK_CHAR's glyph.

    Returns:
        The glyph's columns, left to right.
    """
    code = ord(ch)
    if code < FIRST_CHAR or code > LAST_CHAR:
        code = ord(FALLBACK_CHAR)
    start = (code - FIRST_CHAR) * GLYPH_WIDTH
    return FONT[start : start + GLYPH_WIDTH]


def text(fb: "Canvas", s: str, x: int, y: int, c: int = 1) -> int:
    """Draw a line of text with its top-left corner at (x, y).

    Args:
        fb: The framebuffer to draw on.
        s: The text; characters outside printable ASCII draw as FALLBACK_CHAR.
        x: The left column.
        y: The top row.
        c: The colour of the lit pixels; the others are left as they are.

    Returns:
        The column after the last character's gap, where more text would start.
    """
    for ch in s:
        columns = glyph(ch)
        for col in range(GLYPH_WIDTH):
            bits = columns[col]
            for row in range(GLYPH_HEIGHT):
                if bits & (1 << row):
                    fb.pixel(x + col, y + row, c)
        x += GLYPH_ADVANCE
    return x
